<script lang="ts">
  import { viewedMeeting as meeting, viewedRecord as record, viewedState as stateValue, viewedEvents as recordEvents, language, configs, settings } from '../../lib/stores';
  import { exportOne, exportAll, saveRecordState, deleteRecords } from '../../lib/api';
  import { t, dateTime, timeOnly, confirmDialog } from '../../lib/ui';
  import { filterRowsByTag, filterEventsByType, eventTypeCounts, deriveHandEntries } from '../../lib/record-tools';
import { getLiveStatusLabel, getMatchStatusLabel, getParticipantLocationLabel, getRecordSourceLabel } from '../../lib/session-labels';
  import ExportMenu from '../../lib/common/ExportMenu.svelte';
  import StatusBadge from '../../lib/common/StatusBadge.svelte';
  import { statusLabel, statusStyle } from '../../lib/status-style';
  import NameMatchingPanel from '../../lib/NameMatchingPanel.svelte';
  import SortableFilterStack from '../../lib/common/SortableFilterStack.svelte';
  import AttendanceFilterPanel from '../../lib/common/AttendanceFilterPanel.svelte';
  import { nextRecordSort, sortRecordRows, type RecordSortDir, type RecordSortKey } from '../../lib/record-sort';
  import { groupLabel } from '../../lib/group-label';
  let tab = 'attendance';
  let subtab = 'status';
  let status = '';
  let search = '';
  let newest = true;
  let eventType = '';
  let ascending = true;
  let filteredRows: any[] = [];
  let sortKey: RecordSortKey | '' = '';
  let sortDir: RecordSortDir = 'asc';
  $: movement = $record.record?.movementEvents || $record.movementEvents || [];
  $: names = $record.record?.nameChangeEvents || $record.nameChangeEvents || [];
  $: allRows = $record.rows || [];
  $: attendanceRows = allRows.filter((row: any) => !['unmatched', 'guest'].includes(row.matchStatus));
  $: profile = ($configs.profiles || []).find((item: any) => item.id === ($record.record?.selectedProfileId || $record.record?.guessedProfileId)) || ($configs.profiles || []).find((item: any) => item.id === 'default-all');
  $: durationMinutes = Number($record.durationMinutes ?? $record.record?.durationMinutes ?? 0);
  $: durationWhole = Math.max(0, Math.floor(durationMinutes));
  $: durationText = `${String(Math.floor(durationWhole / 60)).padStart(2, '0')}:${String(durationWhole % 60).padStart(2, '0')}`;
  $: manualCount = $stateValue.manualSnapshots?.length || 0;
  $: decisionCount = $stateValue.reconciliationDecisions?.length || 0;
  $: unmatchedCount = allRows.filter((row: any) => row.matchStatus === 'unmatched').length;
  $: guestCount = allRows.filter((row: any) => row.matchStatus === 'guest').length;
  $: exportedAt = $record.record?.exportedAt || $stateValue.exportedAt || $meeting?.exportedAt;
  $: mode = $record.mode || 'generic';
  $: groupNames = [...new Set<string>([...($configs.groups || []).map((g: any) => typeof g === 'string' ? g : g.name || g.group), ...($configs.roster || []).map((p: any) => p.group)].filter(Boolean))];
  $: rows = sortRecordRows(filteredRows, sortKey, sortDir);
  $: events = filterEventsByType(movement, eventType).filter((event: any) => !search || `${event.participant?.screenName || ''} ${event.type || ''}`.toLowerCase().includes(search.toLowerCase())).slice().sort((a: any,b: any) => (Date.parse(a.timestamp)-Date.parse(b.timestamp))*(newest?-1:1));
  $: handEntries = deriveHandEntries($recordEvents);
  $: counts = eventTypeCounts(movement);
  const primary = [['overview','概况','Overview'],['attendance','自动考勤','Auto Attendance'],['events','进出记录','Entry/Exit'],['hands','举手记录','Raise Hand'],['snapshots','手动考勤记录','Manual Attendance Records']];
  const secondary = [['status','状态','Status'],['matching','昵称匹配','Name Matching'],['profile','考勤配置','Attendance Profile'],['names','名称变更','Name Changes']];
  const statusDefs = [['seen','到过','Seen','seen'],['full_present','全程','Full Present','fullPresent'],['late','迟到','Late','late'],['returned','返回','Returned','returned'],['left_early','早退','Left Early','leftEarly'],['missing','缺席','Absent','missing'],['ignored','不计入','Ignored','ignored'],['total','总计','Total','total']];
  $: statItems = statusDefs.filter((d: any) => d[0] !== 'full_present' || mode === 'roster').map((d: any) => ({ id:d[0], label:t(d[1],d[2]), color:statusStyle(d[0]).color, count:d[0] === 'total' ? ($record.summary?.total ?? attendanceRows.length) : ($record.summary?.[d[3]] ?? filterRowsByTag(attendanceRows,d[0]).length) }));
  const movementLabels: Record<string, string[]> = { joinedBefore:['启动时已加入','Already in meeting at startup'], join:['进入会议','Joined meeting'], leave:['离开会议','Left meeting'], waitingRoomJoinFromOutside:['进入等候室','Entered waiting room'], waitingRoomJoinFromMeeting:['移至等候室','Moved to waiting room'], waitingRoomJoinedBefore:['启动时已在等候室','In waiting room at startup'], waitingRoomLeave:['离开等候室','Left waiting room'] };
  function label(pair: string[]) { return t(pair[1], pair[2]); }
  function eventName(type: string) { const pair = movementLabels[type]; return pair ? t(pair[0], pair[1]) : t('未知','Unknown'); }
  async function changeMode(value: string) { await saveRecordState({ mode: value }, 'viewed'); }
  async function handleExport(kind: string) { if (kind === 'all') await exportAll('viewed'); else await exportOne(kind, 'viewed'); }
  function toggleSort(key: RecordSortKey) { const next = nextRecordSort({ key: sortKey, dir: sortDir }, key); sortKey = next.key; sortDir = next.dir; }
  function sortAria(key: RecordSortKey) { return sortKey !== key ? 'none' : sortDir === 'asc' ? 'ascending' : 'descending'; }
  function sortIndicator(key: RecordSortKey) { return sortKey !== key ? '↕' : sortDir === 'asc' ? '↑' : '↓'; }
  async function handleDelete() {
    if (!$meeting?.endedAt || !(await confirmDialog({ title: t('删除考勤记录','Delete Attendance Record'), message: t('确定删除此会议记录吗？此操作无法撤销。','Delete this meeting record? This cannot be undone.'), destructive: true }))) return;
    await deleteRecords([$meeting.instanceId], 'viewed');
  }
</script>

<section class="detail">
  {#if $record.loading}<p class="empty">{t('加载中…','Loading…')}</p>{:else}
  <div class="header">
    <div class="title"><h2>{$meeting?.topic || $meeting?.meetingNumber}</h2><div class="badges"><span>{$record.mode === 'roster' ? t('花名册','Roster') : t('普通模式','Generic')}</span><span>{getRecordSourceLabel($meeting?.source || 'meeting_live',$language as any).label}</span><small>{$meeting?.meetingNumber} · {$record.summary?.total ?? attendanceRows.length} {t('位参与者','participants')}</small></div></div>
    <div class="actions"><ExportMenu labels={{ all:t('导出全部','Export All'), json:t('导出 JSON','Export JSON'), attendance:t('导出考勤 CSV','Export Attendance CSV'), manual:t('导出手动记录 CSV','Export Manual Records CSV') }} onExport={handleExport}/><button class="danger" disabled={!$meeting?.endedAt} onclick={handleDelete}>{t('删除','Delete')}</button></div>
  </div>
  <div class="record-tabs" role="tablist" aria-label={t('记录详情','Record detail')}>{#each primary as item}<button role="tab" aria-selected={tab===item[0]} class:active={tab===item[0]} onclick={() => {tab=item[0];search='';status='';}}>{label(item)}{#if item[0]==='attendance'}<small>{$record.summary?.total ?? ($record.rows || []).length}</small>{:else if item[0]==='events'}<small>{movement.length}</small>{:else if item[0]==='hands'}<small>{handEntries.length}</small>{:else if item[0]==='snapshots'}<small>{$stateValue.manualSnapshots?.length || 0}</small>{/if}</button>{/each}</div>
  {#if tab==='attendance'}
    <div class="secondary" role="tablist" aria-label={t('自动考勤标签','Auto Attendance tabs')}>{#each secondary as item}<button role="tab" aria-selected={subtab===item[0]} class:active={subtab===item[0]} onclick={() => subtab=item[0]}>{label(item)}</button>{/each}</div>
    {#if subtab==='status'}
      <div class="summary-row"><SortableFilterStack items={statItems} active={status} onSelect={(id) => status = status === id ? '' : id} /></div>
      <div class="mode-row"><b>{t('出席情况','Attendance Status')}</b><div class="segmented"><button class:chosen={$record.mode!=='roster'} onclick={() => changeMode('generic')}>{t('普通模式','Generic')}</button><button class:chosen={$record.mode==='roster'} onclick={() => changeMode('roster')}>{t('花名册','Roster')}</button></div></div>
      <AttendanceFilterPanel rows={attendanceRows} roster={$configs.roster || []} configGroups={groupNames} {profile} {mode} language={$language} initiallyOpen={!$settings.filterDefaultsClosed} activeFilter={status} bind:ascending onActiveFilterChange={(value) => status = value} onRows={(value) => filteredRows = value} />
      <div class="table-wrap"><table><thead><tr><th>#</th><th aria-sort={sortAria('name')}><button type="button" class="sort-header" onclick={() => toggleSort('name')}>{t('姓名','Name')} <span class:active={sortKey === 'name'}>{sortIndicator('name')}</span></button></th><th>{t('状态','Status')}</th><th aria-sort={sortAria('score')}><button type="button" class="sort-header" onclick={() => toggleSort('score')}>{t('出勤率','Score')} <span class:active={sortKey === 'score'}>{sortIndicator('score')}</span></button></th><th>{t('标签','Tags')}</th><th>{t('分组','Group')}</th><th>{t('姓名匹配','Name Match')}</th><th aria-sort={sortAria('firstJoin')}><button type="button" class="sort-header" onclick={() => toggleSort('firstJoin')}>{t('首次加入','First Join')} <span class:active={sortKey === 'firstJoin'}>{sortIndicator('firstJoin')}</span></button></th><th aria-sort={sortAria('minutes')}><button type="button" class="sort-header" onclick={() => toggleSort('minutes')}>{t('分钟','Minutes')} <span class:active={sortKey === 'minutes'}>{sortIndicator('minutes')}</span></button></th></tr></thead><tbody>{#each rows as row,i}<tr><td>{i+1}</td><td class="participant-name"><b>{row.canonicalName || row.zoomName}</b><small>{row.pinyin || row.zoomNames?.join(', ')}</small></td><td><StatusBadge status={row.wasLate ? 'late' : row.currentStatus==='leftEarly'?'left_early':row.currentStatus==='missing'?'absent':row.currentStatus==='returnedAfterLongAbsence'?'returned':row.currentStatus==='present'?'full_present':'seen'} label={statusLabel(row.wasLate ? 'late' : row.currentStatus==='leftEarly'?'left_early':row.currentStatus==='missing'?'absent':row.currentStatus==='returnedAfterLongAbsence'?'returned':row.currentStatus==='present'?'full_present':'seen',$language)} /></td><td><span class="score" class:score-high={(row.score || 0)>=95} class:score-mid={(row.score || 0)>=80 && (row.score || 0)<95} class:score-low={(row.score || 0)<80}>{Math.round(row.score || 0)}%</span></td><td><div class="tag-list">{#each (row.tags || []).filter((chip: string) => chip !== 'total' && chip !== 'ignored' && chip !== 'unmatched') as chip}<StatusBadge status={chip} label={statusLabel(chip,$language)} />{/each}</div></td><td class="group-cell" title={groupLabel(row.group, $language)}>{groupLabel(row.group, $language)}</td><td>{#if row.matchStatus === 'matched' || row.canonicalName}<StatusBadge label={t('已关联','Matched')} tone="success" />{:else}—{/if}</td><td>{row.firstJoinAt ? timeOnly(row.firstJoinAt) : '—'}</td><td>{Math.round(row.totalPresenceMinutes || 0)}</td></tr>{:else}<tr><td colspan="9" class="empty">{t('没有符合条件的参与者','No matching participants')}</td></tr>{/each}</tbody></table></div>
    {:else if subtab==='matching'}<NameMatchingPanel rows={$record.rows || []} decisions={$stateValue.reconciliationDecisions || []} roster={$configs.roster || []} aliases={$configs.aliases || []} nameChanges={names} language={$language} readOnly={true}/>
    {:else if subtab==='profile'}<div class="meta-grid"><article><small>{t('所选配置','Selected profile')}</small><b>{profile?.name || t('未设定','Not Set')}</b></article><article><small>{t('迟到阈值','Late threshold')}</small><b>{$record.record?.lateAfterMinutes ?? '—'} {t('分钟','min')}</b></article><article><small>{t('返回窗口','Return window')}</small><b>{$record.record?.returnWindowMinutes ?? '—'} {t('分钟','min')}</b></article><article><small>{t('包含分组','Included groups')}</small><b>{($record.record?.selectedIncludedSubgroups || []).join(', ') || t('全部','All')}</b></article></div>
    {:else}<h3>{t('名称变更','Name Changes')} · {names.length}</h3>{#each names.slice().reverse() as item}<article class="event"><time>{dateTime(item.timestamp || item.at)}</time><b>{item.previousScreenName || item.previous_screen_name} → {item.nextScreenName || item.next_screen_name}</b></article>{:else}<p class="empty">{t('没有名称变更','No name changes')}</p>{/each}{/if}
  {:else if tab==='overview'}<h3>{t('会议信息','Meeting Metadata')}</h3><div class="meta-grid">{#each [[t('会议号','Meeting ID'),$meeting?.meetingNumber || '—'],[t('开始时间','Start'),$meeting?.startedAt ? dateTime($meeting.startedAt) : '—'],[t('结束时间','End'),$meeting?.endedAt ? dateTime($meeting.endedAt) : t('进行中','In Progress')],[t('时长','Duration'),durationText],[t('使用的配置','Profile Used'),profile?.name || t('未设定','Not Set')],[t('数据来源','Record Source'),getRecordSourceLabel($meeting?.source || 'meeting_live',$language as any).label],[t('版本号','Revision'),$record.record?.revision ?? '—'],[t('导出状态','Export Status'),exportedAt ? `${t('已导出','Exported')} ${dateTime(exportedAt)}` : t('待导出','Pending Export')],[t('会议 UUID','Meeting UUID'),$record.record?.meetingUUID || $record.record?.meetingUuid || $meeting?.meetingUUID || $meeting?.meetingUuid || $meeting?.uuid || '—']] as card}<article><small>{card[0]}</small><b>{card[1]}</b></article>{/each}</div><h3>{t('操作记录','Operator Actions')}</h3><div class="meta-grid">{#each [[t('手动考勤记录','Manual Attendance Records'),manualCount],[t('名单匹配记录','Matching Decisions'),decisionCount],[t('进出记录','Entry/Exit'),movement.length],[t('未匹配','Unmatched'),unmatchedCount],[t('来宾','Guests'),guestCount]] as card}<article><small>{card[0]}</small><b>{card[1]}</b></article>{/each}</div>
  {:else if tab==='events'}<div class="toolbar"><input aria-label={t('搜索事件','Search events')} placeholder={t('搜索名称或事件','Search name or event')} bind:value={search}/><select bind:value={eventType}><option value="">{t('所有事件','All events')}</option>{#each Object.keys(counts) as type}<option value={type}>{eventName(type)} · {counts[type]}</option>{/each}</select><button onclick={() => newest=!newest}>{newest?t('最新优先','Newest first'):t('最早优先','Oldest first')}</button></div>{#each events as event}<article class="event"><time>{dateTime(event.timestamp)}</time><b>{event.participant?.screenName || '—'}</b><span>{eventName(event.type)}</span></article>{:else}<p class="empty">{t('没有进出记录','No entry or exit events')}</p>{/each}
  {:else if tab==='hands'}<h3>{t('举手事件','Raise Hand Events')} · {handEntries.length}</h3>{#each handEntries.slice().reverse() as entry}<article class="event"><time>{dateTime(entry.timestamp)}</time><b>{entry.screenName}</b><span>{entry.action==='raise'?t('举手','Raised hand'):t('放下手','Lowered hand')}</span></article>{:else}<p class="empty">{t('没有举手记录','No raise hand records')}</p>{/each}<h3>{t('举手快照','Raise Hand Captures')}</h3>{#each $stateValue.raiseHandCaptures || [] as capture}<article class="event"><time>{dateTime(capture.timestamp)}</time><b>{capture.totalCount}</b><span>{(capture.screenNames || []).join(', ')}</span></article>{/each}
  {:else}{#each ($stateValue.manualSnapshots || []).slice().reverse() as snapshot}<details><summary>{dateTime(snapshot.timestamp)} · {snapshot.participants?.length || 0}</summary><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('位置','Location')}</th><th>{t('匹配','Match')}</th></tr></thead><tbody>{#each snapshot.participants || [] as participant}<tr><td>{participant.screenName}</td><td>{getParticipantLocationLabel(participant.location,$language as any) || '—'}</td><td>{participant.matchedCanonicalName || getMatchStatusLabel(participant.matchStatus,$language as any)}</td></tr>{/each}</tbody></table></div></details>{:else}<p class="empty">{t('尚无手动考勤记录','No manual attendance records yet')}</p>{/each}{/if}
  {/if}
</section>
 <style>
 .detail{background:var(--surface);border:1px solid var(--line);border-radius:9px;padding:16px;min-width:0}.header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.title{min-width:0;flex:1}.title h2{font-size:17px;margin:0 0 7px;overflow-wrap:anywhere}.actions{flex:none;display:flex;gap:6px;white-space:nowrap}.actions button{white-space:nowrap}.badges{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.badges span{border:1px solid #b7e7f3;border-radius:20px;color:#0782a7;background:#f1fcff;padding:3px 9px;font-size:10px}.badges small{color:var(--muted);font-size:10px}.record-tabs{display:flex;gap:22px;overflow:auto;border-bottom:1px solid var(--line);margin:13px 0 8px}.record-tabs button{flex:none;width:auto;height:auto;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;padding:8px 6px;color:var(--muted);font-size:11px;white-space:nowrap;justify-content:center}.record-tabs button.active{background:transparent;color:var(--accent);border-bottom-color:var(--accent);font-weight:650}.record-tabs small{font-size:9px}.secondary{display:flex;gap:18px;overflow:auto;border-bottom:1px solid var(--line);margin:0 0 12px}.secondary button{flex:none;width:auto;height:auto;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;padding:7px 5px;font-size:10px;color:var(--muted);white-space:nowrap;justify-content:center}.secondary button.active{background:transparent;border-color:var(--accent);color:var(--accent)}.toolbar,.mode-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:10px 0}.mode-row{justify-content:space-between;font-size:11px;color:var(--muted)}.mode-row b{color:var(--text);font-size:12px}.segmented{display:flex}.segmented button{min-height:27px;padding:4px 9px;font-size:10px;border-radius:0}.segmented button:first-child{border-radius:6px 0 0 6px}.segmented button:last-child{border-radius:0 6px 6px 0}.segmented button.chosen{background:var(--accent-soft);color:var(--accent)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table-wrap table{width:100%;min-width:780px;border-collapse:collapse;font-size:11px}.table-wrap th{background:#f5f6fa;color:#536071;font-size:9px;letter-spacing:.3px;text-transform:uppercase;text-align:left}.sort-header{border:0;background:transparent;padding:0;color:inherit;font:inherit;cursor:pointer}.sort-header:hover{color:var(--accent)}.sort-header span{color:var(--muted)}.sort-header span.active{color:var(--accent)}.table-wrap th,.table-wrap td{padding:8px 9px;border-bottom:1px solid var(--line)}.table-wrap tr:last-child td{border-bottom:0}.table-wrap td:nth-child(2) b,.table-wrap td:nth-child(2) small{display:block}.table-wrap td:nth-child(2) small{color:var(--muted);font-size:9px}.table-wrap .participant-name{max-width:260px;white-space:normal;overflow-wrap:anywhere}.table-wrap .participant-name b,.table-wrap .participant-name small{overflow-wrap:anywhere}.table-wrap .group-cell{max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.score{border-radius:15px;background:#e6fffa;color:#0782a7;padding:4px 8px;font-size:10px;font-weight:700}.score.score-high{background:#ecfdf5;color:#15803d}.score.score-mid{background:#ecfeff;color:#0369a1}.score.score-low{background:#fffbeb;color:#b45309}.tag-list{display:flex;gap:4px;flex-wrap:wrap}.event{display:flex;align-items:center;gap:14px;padding:8px 4px;border-bottom:1px solid var(--line);font-size:11px}.event time{color:var(--muted);min-width:145px}.event span{margin-left:auto;color:var(--muted)}.meta-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px}.meta-grid article{border:1px solid var(--line);border-radius:7px;padding:10px;display:grid;gap:5px;font-size:11px}.meta-grid small,.empty{color:var(--muted)}.empty{text-align:center;padding:20px;font-size:11px}h3{font-size:12px;margin:12px 0 6px}details{padding:8px;border-bottom:1px solid var(--line)}summary{font-size:11px;cursor:pointer}
</style>
